import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d,i as c,S as _}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"速率单调","description":"","frontmatter":{"title":"速率单调","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-monotonic.md","filePath":"cs/rate-monotonic.md","lastUpdated":1789023840000}'),p={name:"cs/rate-monotonic.md"};function E(h,a,m,u,A,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="速率单调" tabindex="-1">速率单调 <a class="header-anchor" href="#速率单调" aria-label="Permalink to &quot;速率单调&quot;">​</a></h1><div class="epigraph"><p>周期越短优先级越高：在独立、可抢占、截止等于周期的假设下，利用率不超过 $n(2^{1/n}-1)$ 则速率单调可调度。</p><footer>—— 据 Liu and Layland, Scheduling Algorithms for Multiprogramming in a Hard-Real-Time Environment, JACM 1973</footer></div><p><a href="/cs/realtime-sched">上一课</a>对照了公平份额与期限，并点名 RM 与 EDF。缺口是把 <strong>RM</strong> 收成可检查的规则：静态优先级按周期（速率）指定，短周期高优先级，以及 Liu–Layland 利用率界限。本课不把响应时间分析（RTA）的迭代公式写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一组周期任务 \\(\\tau_i=(C_i,P_i)\\)，\\(D_i=P_i\\)，独立、可抢占、无锁。要不要在运行时比较截止？RM 说不必：离线按 \\(P_i\\) 排序即可。缺口不是再定义硬实时，而是这条静态赋值以及充分条件 \\(\\sum C_i/P_i \\le n(2^{1/n}-1)\\)（\\(n\\to\\infty\\) 时约 \\(0.69\\)）。超界仍可能可调度，那是充分非必要。</p><p><span class="marginnote">调和周期（一个周期是另一个的整数倍）时界限可放到 1。教学先记一般界限，再承认特例更宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定优先级： \\(P_i\\lt P_j \\Rightarrow \\tau_i\\) 高于 \\(\\tau_j\\)。运行：总是跑当前最高优先级的就绪周期任务，与<a href="/cs/runqueue">运行队列</a>的优先级槽一致。利用率测试作快速拒绝；要精确可用关键瞬间：所有任务同时释放时的最坏。本课不把关键瞬间证明展开。</p>',8)),(e(),s(_,null,{default:i(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%91%A8%E6%9C%9F%E4%BB%BB%E5%8A%A1%E9%9B%86%22%5D%20--%3E%20PRI%5B%22%E7%9F%AD%E5%91%A8%E6%9C%9F%20%3D%20%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20PRI%20--%3E%20TEST%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%E5%85%85%E5%88%86%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20TEST%20--%3E%20RUN%5B%22%E9%9D%99%E6%80%81%E4%BC%98%E5%85%88%E7%BA%A7%E6%8A%A2%E5%8D%A0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 CFS 并存时，RM 队列必须先于公平队列，对照课已说。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RM 最优在「静态优先级」类中（Liu–Layland 假设下）：若某静态赋值可调度，则 RM 也可。它不处理共享锁的反转——那要用<a href="/cs/pi-pcp">PI</a>。切换税与 ISR 必须打进 \\(C_i\\)，否则纸上可调度、板上逾期。这把内核抢占与中断线程化接到期限上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把偶发任务、前馈抖动写成完整 Sporadic Server。也不声称桌面 Linux 的 <code>SCHED_FIFO</code> 自动等于 RM：那只是固定优先级，周期要用户自己对齐。EDF 的动态截止与界限 1 是下一课。</p><p>后课默认：静态期限调度用 RM。若允许运行时谁更急谁跑，下一课 EDF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RM：周期越短优先级越高；利用率 \\(n(2^{1/n}-1)\\) 是充分条件。</li><li>静态类中最优（经典假设下）；锁与 ISR 另计。</li><li>动态最早截止是下一课。</li><li>出处：Liu and Layland, <em>JACM</em> 1973。</li></ul>',8))])}const B=o(p,[["render",E]]);export{P as __pageData,B as default};
